def nhom_tuoi(ages):
    kq = {"0-17": 0, "18-59": 0, "60+": 0}
    for a in ages:
        if a is None or a < 0:
            continue
        if a < 18:
            kq["0-17"] += 1
        elif a < 60:
            kq["18-59"] += 1
        else:
            kq["60+"] += 1
    return kq
